import{_ as e,o as a,c as r,ae as d}from"./chunks/framework.EHGTsUvI.js";const y=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"security/index.md","filePath":"security/index.md"}'),n={name:"security/index.md"};function i(s,t,o,c,l,p){return a(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><p>Palexplorer uses a zero-knowledge, end-to-end encrypted architecture. Files are encrypted before sharing and can only be decrypted by intended recipients.</p><h2 id="cryptographic-primitives" tabindex="-1">Cryptographic Primitives <a class="header-anchor" href="#cryptographic-primitives" aria-label="Permalink to &quot;Cryptographic Primitives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Algorithm</th><th>Library</th></tr></thead><tbody><tr><td>Identity</td><td>Ed25519</td><td>sodium-native</td></tr><tr><td>File encryption</td><td>XChaCha20-Poly1305 secretstream</td><td>sodium-native</td></tr><tr><td>Key wrapping</td><td>ECIES (<code>crypto_box_seal</code>)</td><td>sodium-native</td></tr><tr><td>Chat encryption</td><td>NaCl <code>crypto_box</code> (XSalsa20-Poly1305)</td><td>sodium-native</td></tr><tr><td>Password hashing</td><td>Argon2id</td><td>sodium-native</td></tr><tr><td>Message signing</td><td>Ed25519 detached</td><td>sodium-native</td></tr><tr><td>Content addressing</td><td>SHA-256</td><td>Node.js crypto</td></tr><tr><td>Filename obfuscation</td><td>HMAC-SHA256</td><td>Node.js crypto</td></tr><tr><td>Recovery</td><td>BIP-39 mnemonic</td><td>bip39</td></tr></tbody></table><h2 id="key-hierarchy" tabindex="-1">Key Hierarchy <a class="header-anchor" href="#key-hierarchy" aria-label="Permalink to &quot;Key Hierarchy&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BIP-39 Mnemonic (24 words, 256-bit entropy)</span></span>
<span class="line"><span>  └── Ed25519 Seed (32 bytes)</span></span>
<span class="line"><span>       ├── Ed25519 Keypair (signing, identity)</span></span>
<span class="line"><span>       │   └── Curve25519 Keypair (derived, key exchange)</span></span>
<span class="line"><span>       └── Per-Share Key (random, 32 bytes)</span></span>
<span class="line"><span>             └── Wrapped per-recipient via crypto_box_seal</span></span></code></pre></div><h2 id="threat-model" tabindex="-1">Threat Model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat Model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Threat</th><th>Mitigation</th></tr></thead><tbody><tr><td>Eavesdropping</td><td>XChaCha20-Poly1305 encryption on all content</td></tr><tr><td>Impersonation</td><td>Ed25519 signatures on all protocol messages</td></tr><tr><td>Key compromise</td><td>Per-share random keys (compromise one share, not all)</td></tr><tr><td>Replay attacks</td><td>Nonce + timestamp in PAL/1.0 envelopes</td></tr><tr><td>Metadata leakage</td><td>Encrypted filename manifest, HMAC-obfuscated torrent names</td></tr><tr><td>Server compromise</td><td>Core works without servers; servers never see plaintext</td></tr><tr><td>Extension malware</td><td>AST analysis, Worker sandbox, permission model, signatures</td></tr></tbody></table><h2 id="learn-more" tabindex="-1">Learn More <a class="header-anchor" href="#learn-more" aria-label="Permalink to &quot;Learn More&quot;">​</a></h2><ul><li><a href="/security/encryption.html">Encryption</a> — File and chat encryption details</li><li><a href="/security/keys.html">Key Management</a> — Storage, derivation, recovery</li><li><a href="/security/access-control.html">Access Control</a> — Permissions, roles, policies</li></ul>`,10)])])}const m=e(n,[["render",i]]);export{y as __pageData,m as default};
